async function testEngine(){
 setTesting(true);setConfigMessage('');
 try{
  if(draftProvider==='runpod'){
   const response=await fetch('/api/runpod/config',{cache:'no-store'});
   const data=await responseJSON<{configured:boolean}>(response);
   if(!data.configured)throw Error('Runpod is not configured. Set RUNPOD_API_KEY in the app server environment and restart it.');
   setProvider('runpod');setConnected(true);
   setConfigMessage('Runpod API key is configured. Endpoint access will be checked when you generate.');
   addEvent('Runpod Chatterbox Turbo selected');return
  }
  const url=validURL(draftEngine);
  const response=await fetch(url+'/api/health',{headers:draftToken?{Authorization:'Bearer '+draftToken}:{}});
  if(!response.ok)throw Error('Engine responded with HTTP '+response.status+'. Check the URL and access token.');
  const data=await response.json() as {runners?:{chatterbox?:{ready:boolean};whisper?:{ready:boolean}}};
  if(!data.runners?.chatterbox||!data.runners?.whisper)throw Error('This URL is not your Turk_Ai notebook engine. Paste the Cloudflare URL from its Web App cell.');
  if(!data.runners.chatterbox.ready||!data.runners.whisper.ready)throw Error('The engine is reachable, but a voiceover or Whisper runner is missing. Run the notebook Warm-Up Tools cell first.');
  setConfigMessage('Connection successful. Your engine is ready.');setEngine(url);setProvider('colab');setToken(draftToken);setConnected(true);
  addEvent('Engine connected successfully')
 }catch(error){
  setConnected(false);setConfigMessage(error instanceof Error?error.message:'Could not reach the engine. Check its URL and CORS settings.')
 }finally{setTesting(false)}
}
function validURL(value:string){const u=new URL(value);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw Error('Use an HTTPS URL, or localhost for local development.');if(u.username||u.password||u.search||u.hash)throw Error('Use a base URL without credentials or query parameters.');return u.href.replace(/\/$/,'')}
