async function refreshRunpodHistory(ownerId:string){if(activeHistoryUserId!==ownerId)return;const response=await fetch('/api/runpod/history',{cache:'no-store'});const data=await responseJSON<{items:RecordItem[]}>(response);if(activeHistoryUserId===ownerId)setRecords(current=>mergeRecordLists(current,data.items||[]))}
