async function responseJSON<T=unknown>(r:Response):Promise<T>{const data:unknown=await r.json().catch(()=>({detail:`Engine returned HTTP ${r.status}`}));if(!r.ok){const body=data&&typeof data==='object'?data as Record<string,unknown>:{};throw Error(typeof body.error==='string'?body.error:typeof body.detail==='string'?body.detail:`Engine request failed (${r.status})`)}return data as T}
async function watchJob(id:string,signal:AbortSignal){return new Promise<JobCompletion>((resolve,reject)=>{let done=false;let retries=0;let socket:WebSocket;const deadline=setTimeout(()=>finish(Error('The job timed out. Check the Colab console.')),45*60*1000);let reconnect:ReturnType<typeof setTimeout>|undefined;function finish(error?:Error,completion:JobCompletion={}){if(done)return;done=true;clearTimeout(deadline);clearTimeout(reconnect);signal.removeEventListener('abort',onAbort);socket?.close();if(error)reject(error);else resolve(completion)}function onAbort(){finish(new DOMException('Aborted','AbortError'))}signal.addEventListener('abort',onAbort,{once:true});function connect(){if(signal.aborted)return onAbort();const url=new URL(engine);url.protocol=url.protocol==='https:'?'wss:':'ws:';url.pathname=url.pathname.replace(/\/$/,'')+'/ws/'+encodeURIComponent(id);socket=new WebSocket(url);socket.onmessage=event=>{try{const data=JSON.parse(event.data);if(data.status==='completed')return finish(undefined,data as JobCompletion);if(data.status==='failed')return finish(Error(data.message||'The engine job failed. Check Colab logs.'));if(data.message){const message=String(data.message);setJobStatus(message.length>160?message.slice(0,157)+'…':message);if(data.type==='status'||/error|loaded|loading|saved|chunk|done/i.test(message))addEvent(message.slice(0,200));const match=message.match(/(?:chunk|segment)\s*(\d+)\s*[/]\s*(\d+)/i);if(match)setProgress(Math.min(99,Math.round(Number(match[1])/Number(match[2])*100)))}}catch{}};socket.onclose=()=>{if(!done&&retries++<5)reconnect=setTimeout(connect,2000);else if(!done)finish(Error('Live connection was lost. Your job may still be running in Colab.'))};socket.onerror=()=>socket.close()}connect()})}
function retryAfterMs(value:string|null){if(!value)return;const seconds=Number(value);if(Number.isFinite(seconds)&&seconds>=0)return seconds*1000;const date=Date.parse(value);return Number.isFinite(date)?Math.max(0,date-Date.now()):undefined}
function waitForPoll(ms:number,signal:AbortSignal){return new Promise<void>((resolve,reject)=>{if(signal.aborted)return reject(new DOMException('Aborted','AbortError'));const timer=setTimeout(()=>{signal.removeEventListener('abort',cancel);resolve()},ms);function cancel(){clearTimeout(timer);reject(new DOMException('Aborted','AbortError'))}signal.addEventListener('abort',cancel,{once:true})})}
async function watchRunpodJob(id:string,signal:AbortSignal){const deadline=Date.now()+45*60*1000;const pollSchedule=[2000,2000,2000,2000,2000,3000,5000,8000,13000,15000];let pollIndex=0;while(Date.now()<deadline){if(signal.aborted)throw new DOMException('Aborted','AbortError');const response=await fetch('/api/runpod/chatterbox/'+encodeURIComponent(id),{cache:'no-store',signal});if(response.status===429){const retryAfter=retryAfterMs(response.headers.get('Retry-After'));const backoff=pollSchedule[Math.min(pollIndex++,pollSchedule.length-1)];await waitForPoll(retryAfter===undefined?backoff*(.8+Math.random()*.4):retryAfter*(1+Math.random()*.2),signal);continue}const data=await responseJSON<{status:string;error?:string}>(response);if(data.status==='COMPLETED')return;if(data.status==='FAILED')throw Error(data.error||'Runpod voice generation failed.');setJobStatus(data.status==='IN_QUEUE'?'Queued - waiting for a Runpod GPU...':'Generating with Runpod Chatterbox Turbo...');const backoff=pollSchedule[Math.min(pollIndex++,pollSchedule.length-1)];await waitForPoll(backoff*(.8+Math.random()*.4),signal)}throw Error('The Runpod job timed out. Check the Runpod console.')}
async function generate(){
 if(busy)return;
 if(!authUserId){setToast('Sign in before generating or transcribing.');return}
 const ownerId=authUserId;
 if(!engineAvailable)return showConfig();
 if(tool==='voice'&&!script.trim())return;
 if(tool==='voice'&&(provider==='colab'||runpodVoiceSource==='reference')&&!reference)return;
 if(tool==='transcript'&&!audio)return;
 if(tool==='voice'&&(provider==='colab'||runpodVoiceSource==='reference')&&!consent){setError('Confirm that you have permission to use this reference voice.');return}
 const kind=tool==='voice'?'voice':'transcript';
 setBusy(true);setJobTool(kind);setError('');setProgress(0);setJobStatus('Uploading your input…');
 if(kind==='voice'){setResultDownloadURL('');setResultAudio(null)}
 addEvent(kind==='voice'?'Voiceover generation started':'Audio transcription started');
 const controller=new AbortController();abort.current=controller;jobId.current='';
 try{
  if(kind==='voice'&&provider==='runpod'){
   const form=new FormData();form.append('prompt',script);form.append('title',title);form.append('voice',runpodVoice);
   if(runpodVoiceSource==='reference'&&reference){form.append('reference',reference);form.append('consent',String(consent))}
   const start=await responseJSON<{id:string;status?:string}>(await fetch('/api/runpod/chatterbox',{method:'POST',body:form,signal:controller.signal}));
   if(!start.id)throw Error('Runpod did not return a job ID.');
   jobId.current=start.id;setJobStatus('Queued - waiting for a Runpod GPU...');
   await watchRunpodJob(start.id,controller.signal);
   if(activeHistoryUserId!==ownerId)return;
   const response=await fetch('/api/runpod/chatterbox/'+encodeURIComponent(start.id)+'/audio',{signal:controller.signal});
   if(!response.ok)await responseJSON(response);
   const blob=await response.blob();if(activeHistoryUserId!==ownerId)return;setResultAudio(blob);setResultTitle(title.trim()||'voiceover');
   const item:RecordItem={id:start.id,type:'voice',title:title.trim()||'Untitled voiceover',date:Date.now(),serverRunpod:true,expiresAt:Date.now()+12*60*60*1000,voice:runpodVoice};
   setRecords(current=>[item,...current.filter(record=>record.id!==item.id)]);
   try{await refreshRunpodHistory(ownerId)}catch{setToast('Voiceover is ready, but its Hostinger history could not be refreshed.')}
   try{await refreshTtsQuota(ownerId)}catch{setToast('Voiceover is ready, but quota usage could not be refreshed.')}
  }else{
  const form=new FormData();form.append('warm','false');
  if(kind==='voice'){
   form.append('mode','single');form.append('script',new File([script],'script.txt',{type:'text/plain'}));
   form.append('temperature',String(expressiveness));form.append('pause',String(pause));
   form.append('max_chars',String(chunk));form.append('ref_audio',reference!)
  }else{
   form.append('file',audio!);form.append('language',language);
   form.append('min_seconds','0');form.append('max_seconds','0')
  }
  const start=await responseJSON<{job_id:string}>(await fetch(engine+(kind==='voice'?'/chatterbox/start':'/whisper/start'),{method:'POST',headers:authHeaders(),body:form,signal:controller.signal}));
  if(!start.job_id)throw Error('The engine did not return a job ID. Check the notebook console.');
  jobId.current=start.job_id;setJobStatus('Queued — waiting for your GPU…');
  const completion=await watchJob(start.job_id,controller.signal);
  if(activeHistoryUserId!==ownerId)return;
  const fileURL=(key:string)=>engine+'/file/'+encodeURIComponent(start.job_id)+'/'+key;
  if(kind==='voice'){
   const driveURL=driveDownloadURL(completion.downloads?.audio);
   if(driveURL){
    setResultDownloadURL(driveURL);setResultTitle(title.trim()||'voiceover');
    setProgress(100);setJobStatus('Saved to Drive — download is ready');
    addEvent('Voiceover saved to Drive — download is ready');
    const item:RecordItem={id:uid(),type:'voice',title:title.trim()||'Untitled voiceover',date:Date.now(),script,downloadURL:driveURL};
    await storeResult(item,ownerId);
    void fetch(fileURL('audio'),{headers:authHeaders(),signal:controller.signal}).then(async response=>{
     if(!response.ok)throw Error('The preview could not be loaded from the engine.');
     const blob=await response.blob();if(activeHistoryUserId!==ownerId)return;const completedItem={...item,audio:blob};
     setResultAudio(blob);setRecords(records=>records.map(record=>record.id===item.id?completedItem:record));
     try{await historyWrite(ownerId,completedItem)}catch{setToast('Drive download is ready, but its audio preview could not be saved to account history.')}
    }).catch(()=>setToast('Drive download is ready. The in-app audio preview could not be loaded.'));
   }else{
    const response=await fetch(fileURL('audio'),{headers:authHeaders(),signal:controller.signal});
    if(!response.ok)throw Error('Audio download failed. Open the notebook’s own interface to retrieve it.');
    const blob=await response.blob();if(activeHistoryUserId!==ownerId)return;setResultAudio(blob);setResultTitle(title.trim()||'voiceover');
    await storeResult({id:uid(),type:'voice',title:title.trim()||'Untitled voiceover',date:Date.now(),script,audio:blob},ownerId)
   }
  }else{
   const [rawSegments,rawWords]=await Promise.all(['segments','words'].map(async key=>{const response=await fetch(fileURL(key),{headers:authHeaders(),signal:controller.signal});return responseJSON(response)}));
   if(!Array.isArray(rawSegments)||!Array.isArray(rawWords))throw Error('Invalid transcript files from the engine.');
   const wordList=rawWords as Word[];
   const result:Segment[]=(rawSegments as Segment[]).map(s=>({...s,words:wordList.filter(w=>w.start>=s.start-.05&&w.start<s.end)}));
   if(!result.length)throw Error('No speech was detected in this audio.');
   setSegments(result);setDetectedLanguage(language==='auto'?'Auto-detected':language);setTab('Transcript');
   await storeResult({id:uid(),type:'transcript',title:audio!.name,date:Date.now(),segments:result,language:language==='auto'?'Auto-detected':language},ownerId)
  }
  }
  setConnected(true);setProgress(100);setJobStatus('Completed');
  addEvent(kind==='voice'?'Voiceover ready — saved to history':'Transcript ready — saved to history')
 }catch(e){
  if(e instanceof DOMException&&e.name==='AbortError')addEvent('Job stopped');
  else{setError(e instanceof Error?e.message:'Request failed. Check engine connection and CORS.');addEvent('Job failed — check the error message')}
 }finally{setBusy(false);abort.current=null;jobId.current=''}
}
async function cancel(){const activeJob=jobId.current;abort.current?.abort();if(activeJob&&jobTool==='voice'&&provider==='runpod'){void fetch('/api/runpod/chatterbox/'+encodeURIComponent(activeJob),{method:'DELETE'}).then(response=>{if(!response.ok)throw Error('Runpod did not confirm cancellation')}).catch(()=>setToast('Stop was requested, but Runpod cancellation could not be confirmed. Check the Runpod console.'))}else if(activeJob){void fetch(engine+'/cancel/'+encodeURIComponent(activeJob),{method:'POST',headers:authHeaders()}).then(response=>{if(!response.ok)throw Error('Engine did not confirm cancellation')}).catch(()=>setToast('Stop was requested, but the engine did not confirm cancellation.'))}setJobStatus('Stop requested')}
async function chooseAudio(file:File|undefined){if(!file)return;if(file.size>100*1024*1024)return setToast('Choose audio smaller than 100 MB.');if(!/\.(wav|mp3|m4a|flac|ogg|aac|wma)$/i.test(file.name))return setToast('Choose a WAV, MP3, M4A, FLAC, OGG, AAC or WMA file.');setAudio(file);setSegments([]);setError('')}
async function recordVoice(){if(recording){capture.current?.stop();setRecording(false);return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});micStream.current=stream;const recorder=new MediaRecorder(stream);const chunks:BlobPart[]=[];recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{const blob=new Blob(chunks,{type:recorder.mimeType});toWav(blob).then(wav=>setReference(new File([wav],'recorded-reference.wav',{type:'audio/wav'}))).catch(()=>setToast('Could not encode the recording. Upload WAV or MP3 instead.'));stream.getTracks().forEach(t=>t.stop());setRecording(false)};capture.current=recorder;recorder.start();setRecording(true)}catch{setToast('Microphone access is unavailable. You can upload a reference sample instead.')}}
async function loadRecord(item:RecordItem){if(busy)return setToast('Wait for the active job to finish first.');setTool(item.type);setError('');if(item.type==='voice'){setTitle(item.title);setScript(item.script||'');setResultDownloadURL(item.downloadURL||'');setResultTitle(item.title);if(item.serverRunpod){try{const response=await fetch('/api/runpod/chatterbox/'+encodeURIComponent(item.id)+'/audio',{cache:'no-store'});if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(typeof data.error==='string'?data.error:'Could not load generated audio.')}setResultAudio(await response.blob())}catch(error){setResultAudio(null);setToast(error instanceof Error?error.message:'Could not load generated audio.');return}}else setResultAudio(item.audio||null)}else{setResultDownloadURL('');setSegments(item.segments||[]);setDetectedLanguage(item.language||'');setTab('Transcript')}setToast('Opened from history')}
function exportTranscript(format:string){let text='';let type='text/plain';if(format==='srt'||format==='vtt'){text=subtitles(mode==='words'?words.map(w=>({start:w.start,end:w.end,text:w.word})):lines,format);type=format==='vtt'?'text/vtt':'application/x-subrip'}else if(format==='json'){text=JSON.stringify({language:detectedLanguage,segments:lines,words},null,2);type='application/json'}else{text=lines.map(s=>`[${stamp(s.start).slice(0,8)}] ${s.text.trim()}`).join('\n')}download(new Blob([text],{type}),`transcript.${format}`)}
async function copyTranscript(){try{await navigator.clipboard.writeText(lines.map(s=>s.text.trim()).join('\n'));setToast('Transcript copied')}catch{setToast('Clipboard unavailable. Download the transcript instead.')}}
async function downloadVoiceover(){
 if(!resultAudio)return;
 if(outputFormat==='wav'){download(resultAudio,safeName(resultTitle)+'.wav');return}
 setConvertingAudio(true);
 let context:AudioContext|undefined;
 try{
  const {Mp3Encoder}=await import('@breezystack/lamejs');
  context=new AudioContext();
  const decoded=await context.decodeAudioData(await resultAudio.arrayBuffer());
  const channels=Math.min(decoded.numberOfChannels,2);
  const pcm=Array.from({length:channels},(_,channel)=>{
   const samples=decoded.getChannelData(channel),output=new Int16Array(samples.length);
   for(let i=0;i<samples.length;i++){const sample=Math.max(-1,Math.min(1,samples[i]));output[i]=sample<0?sample*32768:sample*32767}
   return output;
  });
  const encoder=new Mp3Encoder(channels,decoded.sampleRate,128);
  const chunks:BlobPart[]=[];
  for(let offset=0;offset<pcm[0].length;offset+=1152){
   const left=pcm[0].subarray(offset,offset+1152);
   const encoded=channels===2?encoder.encodeBuffer(left,pcm[1].subarray(offset,offset+1152)):encoder.encodeBuffer(left);
   if(encoded.length)chunks.push(new Uint8Array(encoded));
  }
  const finalChunk=encoder.flush();
  if(finalChunk.length)chunks.push(new Uint8Array(finalChunk));
  if(!chunks.length)throw Error('The audio could not be encoded.');
  download(new Blob(chunks,{type:'audio/mpeg'}),safeName(resultTitle)+'.mp3');
 }catch(error){setToast(error instanceof Error?'Could not create MP3: '+error.message:'Could not create the MP3 download.')}
 finally{if(context&&context.state!=='closed')await context.close();setConvertingAudio(false)}
}
