useEffect(()=>{const onKey=(e:KeyboardEvent)=>{const el=e.target as HTMLElement;if(el.matches('input,textarea,select')||el.isContentEditable||e.metaKey||e.ctrlKey||e.altKey)return;if(e.key==='1')setTool('voice');if(e.key==='2')setTool('transcript');if(e.key==='Escape')setConfigOpen(false)};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[]);
const pending=busy&&jobTool===tool;
