const referenceUpload=<><div className="field-row reference-label"><label>Reference voice <span className="optional">Required</span></label><span className="small-muted">10-20 seconds recommended</span></div>{reference?<div className="uploaded-reference"><div className="file-detail"><span className="file-icon"><AudioLines size={19}/></span><div><b>{reference.name}</b><small>{(reference.size/1024).toFixed(0)} KB · Reference sample</small></div><button aria-label="Remove reference" className="icon-button" onClick={()=>{setReference(null);setConsent(false)}}><X size={15}/></button></div><audio controls src={referenceURL}/><label className="consent"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/>I own this voice or have permission to use it.</label></div>:<div className="reference-drop"><span className="upload-circle"><Mic2 size={20}/></span><div><label className="file-label reference-file"><strong>Upload a voice sample</strong><input type="file" accept="audio/*" onChange={e=>{const f=e.target.files?.[0];if(f&&f.size<=20*1024*1024&&/\.(wav|mp3|m4a|flac|ogg)$/i.test(f.name)){setReference(f);setConsent(false)}else if(f)setToast('Choose a WAV, MP3, M4A, FLAC or OGG sample under 20 MB.')}}/></label><p>A reference sample is required for voice cloning.</p></div><button className={recording?'record-button recording':'record-button'} onClick={recordVoice} aria-label={recording?'Stop recording reference':'Record reference voice'}>{recording?<Square size={14}/>:<Mic2 size={14}/>}</button></div>}</>;
const referenceInput=<>{outputFormatInput}{referenceUpload}</>;
